#include <vector>
#include <algorithm>

class Solution {
public:
    int minMaxLightWaitTime(std::vector<std::vector<int>>& lights, int cycle) {
        int maxWait = 0;
        for (auto& l : lights) {
            int redDuration = cycle - (l[1] - l[0]);
            maxWait = std::max(maxWait, redDuration);
        }
        return maxWait;
    }
};

class Solution {
    public int minMaxLightWaitTime(int[][] lights, int cycle) {
        int maxWait = 0;
        for (int[] l : lights) {
            int redDuration = cycle - (l[1] - l[0]);
            maxWait = Math.max(maxWait, redDuration);
        }
        return maxWait;
    }
}

function minMaxLightWaitTime(lights, cycle) {
    let maxWait = 0;
    for (const [start, end] of lights) {
        const redDuration = cycle - (end - start);
        maxWait = Math.max(maxWait, redDuration);
    }
    return maxWait;
}
